// /frontend-react/src/components/MedicationHistoryPage.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

// --- MOCK DATA ---
const detail = {
    title: "Medications",
    simpleInfo: "You currently take Blood Pressure Pill (5mg) and a Multivitamin. Both taken in the morning. No recent changes.",
    pdfLink: "Link_to_detailed_Medication_History_Report.pdf",
    color: { bg: '#E8F0FE', border: '#1A73E8', emoji: '💊' },
};

const PHONE_MAX_WIDTH = '450px';

function MedicationHistoryPage({ isEasyMode, goToPage, onMenuClick }) {
    const { t } = useTranslation();
    
    // --- Styles ---
    
    // Main text style - clean, large, high contrast
    const summaryTextStyle = {
        fontSize: isEasyMode ? '36px' : '22px',
        lineHeight: '1.4',
        fontWeight: 'bold',
        color: '#333',
        margin: '0 auto 40px auto', // Increased bottom margin
        maxWidth: '350px',
        textAlign: 'center',
    };
    
    // Icon and Simple Summary Container
    const iconContainerStyle = {
        textAlign: 'center',
        margin: '30px auto',
        padding: '20px',
        maxWidth: '380px',
        borderBottom: '1px solid #ddd',
        borderTop: '1px solid #ddd',
    };

    const preciseButtonStyle = {
        padding: '15px 30px', // Slightly wider button
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        marginTop: '10px', // Reduced top margin
        backgroundColor: '#DC3545', // High-contrast action color (Red)
        color: 'white',
        boxShadow: '0 4px 10px rgba(0,0,0,0.3)',
        transition: 'background-color 0.2s',
    };

    const handleViewPrecise = () => {
        alert(`Opening PRECISE REPORT for ${detail.title} \nLink: ${detail.pdfLink}`);
        console.log(`Precise Report Link: ${detail.pdfLink}`);
    };

    return (
        <div 
            style={{ padding: '0 20px 20px 20px', maxWidth: PHONE_MAX_WIDTH, margin: '0 auto' }}
        >
            <HeaderBar
                title={detail.title}
                // Back button goes back to the list of history items (MedicalHistory page)
                onBackClick={() => goToPage('medical-history')} 
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '60px 0 20px 0', color: detail.color.border, textAlign: 'center' }}>
                {t('history_details.simple_summary')}
            </h2>

            {/* --- Easy Mode Summary Content (Clean, unboxed text) --- */}
            <div style={iconContainerStyle}>
                <span style={{ fontSize: isEasyMode ? '90px' : '60px', display: 'block', marginBottom: '15px' }}>
                    {detail.color.emoji}
                </span>
                <p style={summaryTextStyle}>
                    {detail.simpleInfo}
                </p>
            </div>
            
            {/* --- Call to Action for Caregivers/Others --- */}
            <h3 style={{ fontSize: isEasyMode ? '30px' : '20px', margin: '40px 0 10px 0', textAlign: 'center', color: '#666' }}>
                {t('history_details.precise_access_prompt')}
            </h3>

            <div style={{ textAlign: 'center' }}>
                <button onClick={handleViewPrecise} style={preciseButtonStyle}>
                    {t('history_details.view_precise_report')}
                </button>
                <p style={{ fontSize: isEasyMode ? '18px' : '12px', marginTop: '15px', color: '#999' }}>
                    {t('history_details.precise_report_note')}
                </p>
            </div>
        </div>
    );
}

export default MedicationHistoryPage;
